contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function testDistributorUpdate(address d) public {
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.setRewardDistributor.selector, d));
        require(ok, "setRewardDistributor reverted");
        assert(c.rewardDistributor() == d);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address d) public {
        require(d != address(0), "d must be nonzero");
        c.setRewardDistributor(d);
        assert(c.rewardDistributor() == d);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address d1, address d2) public {
        require(d2 != address(0), "zero distributor");
        c.setRewardDistributor(d1);
        c.setRewardDistributor(d2);
        assert(c.rewardDistributor() == d2);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public {
        require(c.owner() == address(this), "test must be owner");
        c.addReward(address(this));
        c.setRewardDistributor(address(this));
        c.notifyRewardAmount(address(this), 1e24);
        assert(c.rewardPeriodFinish(address(this)) == uint40(block.timestamp + 86400 * 7));
    }
    fallback(bytes calldata input) external payable returns (bytes memory) {
        if (input.length >= 4 && bytes4(input) == 0x23b872dd) {
            return abi.encode(true);
        }
        return "";
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address token, uint256 amount) public {
        require(amount > 0 && amount <= type(uint216).max);
        c.addReward(token);
        c.setRewardDistributor(address(this));
        c.notifyRewardAmount(token, amount);
        assert(c.rewardData(token).rewardRate == amount / c.DURATION());
    }
    receive() external payable {}
}
